## Setup do Projeto

```bash
# Criar projeto NestJS
npm i -g @nestjs/cli
nest new minha-api
cd minha-api

# Instalar dependências
npm i @prisma/client @nestjs/config @nestjs/jwt @nestjs/passport passport passport-jwt bcrypt class-validator class-transformer
npm i -D prisma @types/passport-jwt @types/bcrypt
```

## Configurar Prisma

```bash
npx prisma init
```

Defina o schema em `prisma/schema.prisma`:

```typescript
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  name      String
  password  String
  role      Role     @default(USER)
  posts     Post[]
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model Post {
  id        String   @id @default(cuid())
  title     String
  content   String
  published Boolean  @default(false)
  author    User     @relation(fields: [authorId], references: [id])
  authorId  String
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

enum Role {
  USER
  ADMIN
}
```

## Prisma Service

```typescript
@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit {
  async onModuleInit() {
    await this.$connect();
  }
}
```

## Autenticação JWT

```typescript
@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwt: JwtService,
  ) {}

  async register(dto: RegisterDto) {
    const hash = await bcrypt.hash(dto.password, 12);
    const user = await this.prisma.user.create({
      data: { email: dto.email, name: dto.name, password: hash },
    });
    return this.generateToken(user.id, user.email);
  }

  async login(dto: LoginDto) {
    const user = await this.prisma.user.findUnique({ where: { email: dto.email } });
    if (!user || !(await bcrypt.compare(dto.password, user.password))) {
      throw new UnauthorizedException('Credenciais inválidas');
    }
    return this.generateToken(user.id, user.email);
  }

  private generateToken(userId: string, email: string) {
    const payload = { sub: userId, email };
    return { access_token: this.jwt.sign(payload) };
  }
}
```

## CRUD com Validação

```typescript
@Controller('posts')
@UseGuards(JwtAuthGuard)
export class PostsController {
  constructor(private prisma: PrismaService) {}

  @Post()
  create(@Body() dto: CreatePostDto, @Req() req) {
    return this.prisma.post.create({
      data: { ...dto, authorId: req.user.id },
    });
  }

  @Get()
  findAll(@Query() query: PaginationDto) {
    return this.prisma.post.findMany({
      skip: query.skip ?? 0,
      take: query.take ?? 20,
      where: { published: true },
      include: { author: { select: { name: true } } },
      orderBy: { createdAt: 'desc' },
    });
  }
}
```

## Tratamento Global de Erros

```typescript
@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse();
    const status = exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;

    response.status(status).json({
      statusCode: status,
      message: exception instanceof HttpException
        ? exception.message
        : 'Erro interno do servidor',
      timestamp: new Date().toISOString(),
    });
  }
}
```

## Partial\<T\>

Torna todas as propriedades opcionais. Perfeito para updates parciais:

```typescript
interface User {
  name: string;
  email: string;
  age: number;
}

function updateUser(id: string, data: Partial<User>) {
  // data pode ter qualquer combinação de name, email, age
}

updateUser('1', { name: 'Ivan' }); // OK
updateUser('1', { email: 'ivan@dev.com', age: 25 }); // OK
```

## Pick\<T, K\> e Omit\<T, K\>

Selecionar ou excluir propriedades:

```typescript
type UserPreview = Pick<User, 'name' | 'email'>;
// { name: string; email: string }

type UserWithoutAge = Omit<User, 'age'>;
// { name: string; email: string }
```

## Record\<K, V\>

Mapear chaves para valores:

```typescript
type Role = 'admin' | 'editor' | 'viewer';
type Permissions = Record<Role, string[]>;

const perms: Permissions = {
  admin: ['read', 'write', 'delete'],
  editor: ['read', 'write'],
  viewer: ['read'],
};
```

## Required\<T\>

Oposto do Partial — torna tudo obrigatório:

```typescript
interface Config {
  host?: string;
  port?: number;
  ssl?: boolean;
}

type RequiredConfig = Required<Config>;
// { host: string; port: number; ssl: boolean }
```

## Extract\<T, U\> e Exclude\<T, U\>

Filtrar tipos de union:

```typescript
type Event = 'click' | 'scroll' | 'mousemove' | 'keydown';

type MouseEvent = Extract<Event, 'click' | 'mousemove'>;
// 'click' | 'mousemove'

type NonMouseEvent = Exclude<Event, 'click' | 'mousemove'>;
// 'scroll' | 'keydown'
```

## ReturnType\<T\> e Parameters\<T\>

Inferir tipos de funções:

```typescript
function createUser(name: string, age: number) {
  return { id: crypto.randomUUID(), name, age, createdAt: new Date() };
}

type UserReturn = ReturnType<typeof createUser>;
// { id: string; name: string; age: number; createdAt: Date }

type UserParams = Parameters<typeof createUser>;
// [name: string, age: number]
```

## NonNullable\<T\>

Remover null e undefined:

```typescript
type MaybeString = string | null | undefined;
type DefinitelyString = NonNullable<MaybeString>;
// string
```

## Template Literal Types

```typescript
type HTTPMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';
type APIRoute = '/users' | '/posts';
type Endpoint = `${HTTPMethod} ${APIRoute}`;
// 'GET /users' | 'GET /posts' | 'POST /users' | ...
```

## O Problema com RxJS para Estado Local

RxJS é poderoso para streams assíncronas, mas para estado simples de componentes, BehaviorSubjects adicionam complexidade desnecessária: gerenciar subscriptions, evitar memory leaks, operadores verbosos para transformações simples. Signals resolvem isso.

## Signals Básicos

```typescript
import { signal, computed, effect } from '@angular/core';

// Signal de escrita
const count = signal(0);

// Ler valor
console.log(count()); // 0

// Atualizar
count.set(5);
count.update(v => v + 1);
```

## Computed Signals

Derivar valores reativamente sem subscription manual:

```typescript
const firstName = signal('Ivan');
const lastName = signal('Reis');

const fullName = computed(() => `${firstName()} ${lastName()}`);
// Recalcula automaticamente quando firstName ou lastName mudam

console.log(fullName()); // 'Ivan Reis'
```

## Effect para Side Effects

```typescript
effect(() => {
  console.log(`Usuário mudou para: ${fullName()}`);
  // Executa automaticamente quando qualquer signal dependente muda
});
```

## Signals em Componentes

```typescript
@Component({
  selector: 'app-counter',
  template: `
    <p>Contagem: {{ count() }}</p>
    <button (click)="increment()">+1</button>
    <p>Dobro: {{ double() }}</p>
  `,
})
export class Counter {
  readonly count = signal(0);
  readonly double = computed(() => this.count() * 2);

  increment() {
    this.count.update(v => v + 1);
  }
}
```

## Signal Inputs (Angular 17.1+)

```typescript
@Component({
  selector: 'app-user-card',
  template: `<h3>{{ displayName() }}</h3>`,
})
export class UserCard {
  name = input.required<string>();
  role = input<string>('user');

  displayName = computed(() =>
    `${this.name()} (${this.role()})`
  );
}
```

## Migrando de BehaviorSubject

```typescript
// ANTES (RxJS)
private userSubject = new BehaviorSubject<User | null>(null);
user$ = this.userSubject.asObservable();
setUser(user: User) { this.userSubject.next(user); }

// DEPOIS (Signals)
private readonly _user = signal<User | null>(null);
readonly user = this._user.asReadonly();
setUser(user: User) { this._user.set(user); }
```

## Quando Usar Cada Um

- **Signals**: estado local/global, dados síncronos, propriedades de UI, formulários
- **RxJS**: HTTP requests, WebSockets, eventos complexos com debounce/merge/switch, streams de dados
- **Ambos**: `toSignal()` e `toObservable()` conectam os dois mundos

## Arquitetura

A estratégia mais segura combina dois tokens:

- **Access Token**: JWT de curta duração (15min), enviado no header Authorization
- **Refresh Token**: Token opaco de longa duração (7 dias), armazenado em HTTP-only cookie

Quando o access token expira, o frontend faz uma requisição silenciosa com o refresh token para obter um novo par de tokens.

## Backend: Gerar Tokens

```typescript
class AuthService {
  generateTokens(userId: string) {
    const accessToken = jwt.sign(
      { sub: userId },
      process.env.JWT_SECRET,
      { expiresIn: '15m' }
    );

    const refreshToken = crypto.randomBytes(64).toString('hex');

    // Salvar hash do refresh token no banco
    await this.prisma.refreshToken.create({
      data: {
        token: await bcrypt.hash(refreshToken, 10),
        userId,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      },
    });

    return { accessToken, refreshToken };
  }
}
```

## Backend: Endpoint de Refresh

```typescript
@Post('refresh')
async refresh(@Req() req, @Res() res) {
  const refreshToken = req.cookies['refresh_token'];
  if (!refreshToken) throw new UnauthorizedException();

  const stored = await this.prisma.refreshToken.findFirst({
    where: { userId: req.user?.id, expiresAt: { gt: new Date() } },
  });

  if (!stored || !(await bcrypt.compare(refreshToken, stored.token))) {
    throw new UnauthorizedException();
  }

  // Rotation: invalidar token antigo, gerar novo par
  await this.prisma.refreshToken.delete({ where: { id: stored.id } });
  const tokens = await this.generateTokens(stored.userId);

  res.cookie('refresh_token', tokens.refreshToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000,
    path: '/api/auth/refresh',
  });

  return res.json({ access_token: tokens.accessToken });
}
```

## Frontend: Interceptor Angular

```typescript
export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const authService = inject(AuthService);
  const token = authService.accessToken();

  if (token) {
    req = req.clone({
      setHeaders: { Authorization: `Bearer ${token}` },
    });
  }

  return next(req).pipe(
    catchError(error => {
      if (error.status === 401 && !req.url.includes('refresh')) {
        return authService.refreshToken().pipe(
          switchMap(newToken => {
            const retryReq = req.clone({
              setHeaders: { Authorization: `Bearer ${newToken}` },
            });
            return next(retryReq);
          }),
        );
      }
      return throwError(() => error);
    }),
  );
};
```

## Checklist de Segurança

- Access token curto (15min max)
- Refresh token em HTTP-only cookie (não acessível via JS)
- Flag Secure em produção (HTTPS only)
- SameSite=Strict para prevenir CSRF
- Rotation de refresh token a cada uso
- Limitar path do cookie ao endpoint de refresh
- Salvar apenas hash do refresh token no banco
